def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = []
    op = []
    for h in history:
        my.append(h[0])
        op.append(h[1])

    last_my = my[-1]
    last_op = op[-1]

    opD = 0
    myD = 0
    for i in range(n):
        if op[i] == 'D':
            opD += 1
        if my[i] == 'D':
            myD += 1

    opC = n - opD

    if n >= 10:
        recent = op[-10:]
    else:
        recent = op

    rl = len(recent)
    rd = 0
    rc = 0
    for x in recent:
        if x == 'D':
            rd += 1
        else:
            rc += 1

    if n >= 5:
        recent5 = op[-5:]
    else:
        recent5 = op

    r5D = 0
    r5C = 0
    for x in recent5:
        if x == 'D':
            r5D += 1
        else:
            r5C += 1

    afterD_total = 0
    afterD_pun = 0
    afterC_total = 0
    afterC_pun = 0

    for i in range(n - 1):
        if my[i] == 'D':
            afterD_total += 1
            if op[i + 1] == 'D':
                afterD_pun += 1
        else:
            afterC_total += 1
            if op[i + 1] == 'D':
                afterC_pun += 1

    streak = 0
    i = n - 1
    while i >= 0:
        if my[i] == 'D' and op[i] == 'D':
            streak += 1
            i -= 1
        else:
            break

    remaining = 100 - n

    pure_d = opC == 0
    very_d = n >= 4 and rd >= 3 and rd * 2 >= rl
    heavy_d = n >= 8 and opD * 2 >= n

    c_high = afterC_total >= 3 and afterC_pun * 2 >= afterC_total
    c_low = afterC_total >= 1 and afterC_pun == 0

    d_forgive_always = afterD_total >= 1 and afterD_pun == 0
    d_forgive_good = afterD_total >= 2 and afterD_pun * 3 <= afterD_total
    d_forgive_ok = afterD_total >= 1 and afterD_pun * 2 <= afterD_total
    d_punish_often = afterD_total >= 1 and afterD_pun * 2 >= afterD_total

    d_not_worse = (
        afterD_total >= 3
        and afterC_total >= 3
        and afterD_pun * afterC_total <= afterC_pun * afterD_total
    )

    if pure_d and n >= 2:
        return 'D'

    if very_d and heavy_d and not d_forgive_good:
        return 'D'

    if c_high and rd * 2 >= rl:
        return 'D'

    if last_my == 'D' and last_op == 'D':
        if (rc >= 3 or r5C >= 2) and not heavy_d and not c_high:
            return 'C'
        if streak >= 3 and rc >= 1 and not heavy_d:
            return 'C'
        if c_low and afterD_total >= 1:
            return 'C'
        if heavy_d or very_d or c_high:
            return 'D'
        if d_punish_often:
            if c_high:
                return 'D'
            return 'C'
        return 'C'

    if last_my == 'D' and last_op == 'C':
        if d_not_worse:
            return 'D'
        if d_forgive_always:
            if remaining <= 5 or rd == 0 or d_forgive_good:
                return 'D'
        if d_forgive_good and rd <= 3:
            return 'D'
        if remaining <= 2 and d_forgive_ok:
            return 'D'
        if c_high:
            return 'D'
        if very_d:
            return 'D'
        return 'C'

    if last_my == 'C' and last_op == 'D':
        return 'D'

    if d_not_worse:
        return 'D'

    if d_forgive_always:
        if remaining <= 10 or rd <= 1:
            return 'D'

    if d_forgive_good and rd <= 2:
        if remaining <= 20 or not very_d:
            return 'D'

    if c_high and rd >= 2:
        return 'D'

    if very_d and heavy_d:
        return 'D'

    if remaining == 1 and d_forgive_ok and not heavy_d:
        return 'D'

    return 'C'
